// Parse [aastypes.ISomething] from a map,
// or return an error, if any.
func somethingFromMapWithoutDispatch(
	m map[string]interface{},
) (
	result aastypes.ISomething,
	err error,
) {
	var theStructuralProperty *aastypes.StructuralUnion
	var theMixedProperty *aastypes.MixedUnion
	var theModelTypedProperty *aastypes.ModelTypedUnion
	var theListStructuralProperty []*aastypes.StructuralUnion
	var theListMixedProperty []*aastypes.MixedUnion
	var theListModelTypedProperty []*aastypes.ModelTypedUnion
	var theTupleProperty aascommon.Tuple3[*aastypes.StructuralUnion, *aastypes.MixedUnion, *aastypes.ModelTypedUnion]
	var theOptionalStructuralProperty *aastypes.StructuralUnion
	var theOptionalMixedProperty *aastypes.MixedUnion
	var theOptionalModelTypedProperty *aastypes.ModelTypedUnion

	foundStructuralProperty := false
	foundMixedProperty := false
	foundModelTypedProperty := false
	foundListStructuralProperty := false
	foundListMixedProperty := false
	foundListModelTypedProperty := false
	foundTupleProperty := false

	for k, v := range m {
		switch k {
		case "structuralProperty":
			theStructuralProperty, err = StructuralUnionFromJsonable(v)
			foundStructuralProperty = true

		case "mixedProperty":
			theMixedProperty, err = MixedUnionFromJsonable(v)
			foundMixedProperty = true

		case "modelTypedProperty":
			theModelTypedProperty, err = ModelTypedUnionFromJsonable(v)
			foundModelTypedProperty = true

		case "listStructuralProperty":
			theListStructuralProperty, err = parseArray(v, StructuralUnionFromJsonable)
			foundListStructuralProperty = true

		case "listMixedProperty":
			theListMixedProperty, err = parseArray(v, MixedUnionFromJsonable)
			foundListMixedProperty = true

		case "listModelTypedProperty":
			theListModelTypedProperty, err = parseArray(v, ModelTypedUnionFromJsonable)
			foundListModelTypedProperty = true

		case "tupleProperty":
			theTupleProperty, err = parseTuple3(
				v,
				StructuralUnionFromJsonable,
				MixedUnionFromJsonable,
				ModelTypedUnionFromJsonable,
			)
			foundTupleProperty = true

		case "optionalStructuralProperty":
			theOptionalStructuralProperty, err = StructuralUnionFromJsonable(v)

		case "optionalMixedProperty":
			theOptionalMixedProperty, err = MixedUnionFromJsonable(v)

		case "optionalModelTypedProperty":
			theOptionalModelTypedProperty, err = ModelTypedUnionFromJsonable(v)

		default:
			err = newDeserializationError(
				fmt.Sprintf(
					"Unexpected property: %s",
					k,
				),
			)
			return
		}

		if err != nil {
			mustDeserializationError(err).prependName(k)
			return
		}
	}

	if !foundStructuralProperty {
		err = newDeserializationError(
			"The required property 'structuralProperty' is missing",
		)
		return
	}

	if !foundMixedProperty {
		err = newDeserializationError(
			"The required property 'mixedProperty' is missing",
		)
		return
	}

	if !foundModelTypedProperty {
		err = newDeserializationError(
			"The required property 'modelTypedProperty' is missing",
		)
		return
	}

	if !foundListStructuralProperty {
		err = newDeserializationError(
			"The required property 'listStructuralProperty' is missing",
		)
		return
	}

	if !foundListMixedProperty {
		err = newDeserializationError(
			"The required property 'listMixedProperty' is missing",
		)
		return
	}

	if !foundListModelTypedProperty {
		err = newDeserializationError(
			"The required property 'listModelTypedProperty' is missing",
		)
		return
	}

	if !foundTupleProperty {
		err = newDeserializationError(
			"The required property 'tupleProperty' is missing",
		)
		return
	}

	result = aastypes.NewSomething(
		theStructuralProperty,
		theMixedProperty,
		theModelTypedProperty,
		theListStructuralProperty,
		theListMixedProperty,
		theListModelTypedProperty,
		theTupleProperty,
	)
	result.SetOptionalStructuralProperty(
		theOptionalStructuralProperty,
	)
	result.SetOptionalMixedProperty(
		theOptionalMixedProperty,
	)
	result.SetOptionalModelTypedProperty(
		theOptionalModelTypedProperty,
	)

	return
}

